/** An LWC bundle or a Visualforce page, generated by scripts/classify-components.mjs. */
export interface ComponentInfo {
  /** API name: the LWC bundle folder or the Visualforce page name. */
  name: string;
  /** Apex controller classes: LWC `@salesforce/apex` imports, or a VF page's `controller` and `extensions`. */
  controllers: string[];
  /** Visualforce pages only: the sObject of a `standardController`. */
  standard?: string;
  /** Module pages this component is listed on. */
  modules: string[];
}
